& { $env:PYTHONUTF8 = '1'; $OutputEncoding = [Console]::InputEncoding = [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding; $payload = if ($MyInvocation.ExpectingInput) { $input -join "`n" } else { [Console]::In.ReadToEnd() }; $python = $null
if ($env:TE_PYTHON) {
    $python = Get-Command $env:TE_PYTHON -CommandType Application -All -ErrorAction SilentlyContinue |
        Select-Object -First 1
}
if (-not $python) {
    $candidates = @(foreach ($name in @('python3', 'python', 'py')) {
        Get-Command $name -CommandType Application -All -ErrorAction SilentlyContinue
    })
    $ordered = @($candidates | Where-Object { $_.Source -notlike '*\WindowsApps\*' }) +
        @($candidates | Where-Object { $_.Source -like '*\WindowsApps\*' })
    $old = $null
    foreach ($candidate in $ordered) {
        $probeArgs = @()
        if ($candidate.Name -eq 'py.exe' -or $candidate.Name -eq 'py') { $probeArgs += '-3' }
        if ($candidate.Source -like '*\WindowsApps\*') {
            & $candidate.Source @probeArgs -E -S -c pass *> $null
            if ($LASTEXITCODE -ne 0) { continue }
        }
        & $candidate.Source @probeArgs -E -S -c 'import sys; sys.exit(sys.version_info < (3, 10))' *> $null
        if ($LASTEXITCODE -eq 0) { $python = $candidate; break }
        if ($LASTEXITCODE -eq 1 -and -not $old) { $old = $candidate }
    }
    if (-not $python) { $python = $old }
}
if (-not $python) { $root = if ($env:TOKENECONOMIZER_HOME) { $env:TOKENECONOMIZER_HOME } else { Join-Path $HOME '.tokeneconomizer' }; try { [IO.Directory]::CreateDirectory($root) | Out-Null; [IO.File]::AppendAllText((Join-Path $root 'errors.log'), "te: no Python on PATH (set TE_PYTHON)`n") } catch [IO.IOException] { [Console]::Error.WriteLine($_.Exception.Message) } catch [UnauthorizedAccessException] { [Console]::Error.WriteLine($_.Exception.Message) }; '{}'; exit 0 }; $pythonArgs = @(); if ($python.Name -eq 'py.exe' -or $python.Name -eq 'py') { $pythonArgs += '-3' }; $pythonArgs += @((Join-Path $env:COPILOT_PLUGIN_ROOT 'scripts\te_bootstrap.py'), 'hook', '--host', 'copilot'); $payload | & $python.Source @pythonArgs; exit $LASTEXITCODE }

